package edu.facilities.ui;
import edu.facilities.service.AuthService; import javafx.fxml.*; import javafx.event.*; import javafx.scene.*; import javafx.scene.control.*; import javafx.stage.*; import java.io.*;
public class dashboardcontroller {
 @FXML private Label welcomeLabel; @FXML private Button roomsButton,maintenanceButton,ticketsButton,catalogButton,enrollmentButton,assignmentButton,manageRoomsButton;
 @FXML public void initialize(){var a=AuthService.getInstance();if(!a.isLoggedIn())return;welcomeLabel.setText("Welcome, "+a.getCurrentUser().getUsername()+" ("+a.getCurrentUserType()+")");boolean admin=a.hasRole("ADMIN");boolean student=a.hasRole("STUDENT");manageRoomsButton.setVisible(admin);manageRoomsButton.setManaged(admin);assignmentButton.setVisible(admin);assignmentButton.setManaged(admin);catalogButton.setVisible(student);catalogButton.setManaged(student);enrollmentButton.setVisible(student);enrollmentButton.setManaged(student);}
 @FXML private void openRooms(ActionEvent e)throws IOException{go(e,"/fxml/rooms.fxml");} @FXML private void openMaintenance(ActionEvent e)throws IOException{go(e,"/fxml/maintenanceTicket.fxml");} @FXML private void openTickets(ActionEvent e)throws IOException{go(e,"/fxml/tickets_view.fxml");} @FXML private void openCatalog(ActionEvent e)throws IOException{go(e,"/fxml/student_course_catalog.fxml");} @FXML private void openEnrollment(ActionEvent e)throws IOException{go(e,"/fxml/student_enrollment.fxml");} @FXML private void openAssignment(ActionEvent e)throws IOException{go(e,"/fxml/course_room_assignment.fxml");} @FXML private void logout(ActionEvent e)throws IOException{AuthService.getInstance().logout();go(e,"/fxml/login.fxml");}
 private void go(ActionEvent e,String f)throws IOException{Stage s=(Stage)((Node)e.getSource()).getScene().getWindow();s.setScene(new Scene(FXMLLoader.load(getClass().getResource(f))));}
}
